{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C11", "C28", "C36", "C42", "C23", "C26", "C07", "C55", "C68", "C74", "C75"],
  "contradictory_card_ids": ["C25", "C09", "C80", "C83"],
  "prediction_basis_card_ids": ["C11", "C28", "C36", "C42", "C23", "C26", "C07", "C55"],
  "claims": [
    {
      "claim": "Omadacycline, the closest structurally related tetracycline with clinical oral data, has a measured oral bioavailability of 34.5% in healthy adults after a 300 mg fasted oral dose, with 300 mg oral bioequivalent to 100 mg IV.",
      "card_ids": ["C11", "C28", "C36", "C42"]
    },
    {
      "claim": "The tetracycline parent scaffold has reported human oral bioavailability of 75%, >70%, and 80–90%, supporting meaningful oral absorption for the tetracycline class.",
      "card_ids": ["C23", "C26", "C07"]
    },
    {
      "claim": "L3 oral exposure data for tetracycline show substantial systemic exposure after oral dosing (AUC0-inf 67.4 µg·h/mL after 500 mg), consistent with meaningful oral absorption.",
      "card_ids": ["C55"]
    },
    {
      "claim": "L4 records for tetracycline show favorable dissolution/salt formation and no impairment of intestinal absorption in a rat anaphylaxis model, providing limited supportive context for the absorption component of the tetracycline class.",
      "card_ids": ["C68", "C74", "C75"]
    },
    {
      "claim": "L5 adds no query-specific gut-wall efflux or intestinal metabolism evidence; the tetracycline mucus-barrier records are mechanistic and do not overturn measured human F values, while the remaining L5 records are for unrelated scaffolds.",
      "card_ids": ["C80", "C83", "C79", "C82", "C85", "C90"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C80", "C83"]
    },
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C79", "C81", "C82", "C84", "C85", "C86", "C87", "C88", "C89", "C90"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability, permeability, efflux, or intestinal metabolism record for the query molecule itself.",
    "Transfer from omadacycline and tetracycline is inferred; the query's C7-fluoro and C9-pyrrolidinoacetamido substituents may alter absorption and efflux relative to those comparators.",
    "No formulation, dose, or prandial condition is specified for the query.",
    "No tigecycline-like comparator with a C9 glycyl amide is present in the evidence to directly test the low-F hypothesis.",
    "L5 records are mostly for unrelated scaffolds and do not provide query-specific gut-wall efflux or intestinal metabolism data."
  ],
  "decision_summary": "Predicted high because the most transferable experimental contexts are tetracycline-class molecules with F >=20% (omadacycline 34.5%; tetracycline 75%), and L3/L4 records for tetracycline are consistent with meaningful oral absorption. L5 adds no query-specific gut-wall efflux or intestinal metabolism evidence; tetracycline mucus-barrier records are mechanistic and do not overturn measured human F. The physicochemical low-F prior and formulation-specific low record are acknowledged but do not constitute affirmative threshold-relevant evidence for F <20%; unresolved uncertainty is reflected in moderate confidence and evidence gaps."
}

